class Solution:
    def minimumOperations(self, nums: list[int]) -> int:
        return len(set(x for x in nums if x > 0))

class Solution {
public:
    int minimumOperations(std::vector<int>& nums) {
        std::unordered_set<int> unique_pos;
        for (int x : nums) {
            if (x > 0) unique_pos.insert(x);
        }
        return unique_pos.size();
    }
};

class Solution {
    public int minimumOperations(int[] nums) {
        java.util.Set<Integer> set = new java.util.HashSet<>();
        for (int x : nums) {
            if (x > 0) set.add(x);
        }
        return set.size();
    }
}

var minimumOperations = function(nums) {
    const set = new Set();
    for (const x of nums) {
        if (x > 0) set.add(x);
    }
    return set.size;
};
